use xiom.io;

fn main() {
  let is_weekend: Bool = true;
  let is_sunny: Bool = false;

  if is_weekend {
    if is_sunny {
      io.println("Park day!");
    } else {
      io.println("Movie day!");
    }
  } else {
    io.println("School day");
  }
}
